import cv2, glob, os

frames = sorted(glob.glob('/root/keyframes_*.png'))

templates = {
    'coins': '/root/coin.png',
    'enemies': '/root/enemy.png',
    'turtles': '/root/turtle.png',
}

# load templates grayscale
T = {k: cv2.imread(v, cv2.IMREAD_GRAYSCALE) for k,v in templates.items()}
for k,v in T.items():
    if v is None:
        raise SystemExit(f"Template {k} missing")


def count_matches(img, templ, threshold):
    res = cv2.matchTemplate(img, templ, cv2.TM_CCOEFF_NORMED)
    h, w = templ.shape
    count = 0
    # suppress by zeroing local window
    while True:
        minVal, maxVal, minLoc, maxLoc = cv2.minMaxLoc(res)
        if maxVal < threshold:
            break
        count += 1
        x, y = maxLoc
        x0 = max(0, x - w//4)
        y0 = max(0, y - h//4)
        x1 = min(res.shape[1], x + w)
        y1 = min(res.shape[0], y + h)
        res[y0:y1, x0:x1] = 0
    return count

# quick thresholds (will adjust after seeing output)
thresholds = {'coins': 0.85, 'enemies': 0.8, 'turtles': 0.8}

results = []
for f in frames:
    img = cv2.imread(f, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise SystemExit(f"Failed to load {f}")
    counts = {k: count_matches(img, T[k], thresholds[k]) for k in T}
    results.append((f, counts))

for f, c in results:
    print(f, c)
